def icon(name, size=18, cls=''):
    return f'<svg class="icon {cls}" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#i-{name}"/></svg>'
sprite='<svg aria-hidden="true" width="0" height="0" style="position:absolute;overflow:hidden"><defs>'+''.join(f'<symbol id="i-{name}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{p}</symbol>' for name,p in paths.items())+'</defs></svg>'
def star(cls=''):return f'<svg class="{cls}" viewBox="0 0 100 100" fill="none" aria-hidden="true"><path d="M50 0c0 27.6 22.4 50 50 50-27.6 0-50 22.4-50 50C50 72.4 27.6 50 0 50c27.6 0 50-22.4 50-50Z" fill="currentColor"/></svg>'
def sec(n,t, light=False):return f'<span class="section-label {"section-label-light" if light else ""}"><span class="section-label-index">/{n}</span> {esc(t)}</span>'
def extlink(url,label,cls='',inner=''):
    return f'<a href="{esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="{esc(label)}" class="{cls}">{inner}</a>'

def project_visual(name):
    if name=='moodwave':
        return f'''<div class="visual-inner mood-scene" aria-hidden="true"><div class="music-window"><div class="music-top"><span class="music-mark">{icon('music',12)}</span><span>moodwave</span><span class="music-top-dots">•••</span></div><div class="music-content"><span class="music-eyebrow">YOUR MOOD, YOUR SOUND</span><div class="music-title">Feel everything.</div><div class="music-subtitle">Find your frequency.</div><div class="album-row"><div class="album album-a"><span>SOFT<br>FOCUS</span></div><div class="album album-b"><span>NIGHT<br>DRIVE</span></div><div class="album album-c"><span>DAY<br>DREAM</span></div></div><div class="player">{icon('play',12)}<div class="player-progress"><i></i></div><span>02:36</span></div></div></div><div class="visual-float music-note">{icon('music',22)}</div></div>'''
