        return '''<div class="visual-inner traffic-scene" aria-hidden="true"><div class="traffic-glow"></div><div class="traffic-panel"><div class="traffic-panel-head"><span class="live-indicator"></span> VISION ENGINE <span class="traffic-model">CNN / GTSRB</span></div><div class="traffic-detection"><span class="detection-corner tl"></span><span class="detection-corner tr"></span><span class="detection-corner bl"></span><span class="detection-corner br"></span><div class="road-sign"><span>30</span></div></div><div class="detection-footer"><span>Traffic sign recognition</span><span class="recognised">DETECTED <span>✓</span></span></div></div><span class="visual-coordinate">01.00 / CV</span></div>'''
