approach=''.join(f'''<div class="approach-card"><span class="approach-number">{i+1:02d}/03</span><div class="approach-icon">{icon(ic,22)}</div><h3>{title}</h3><p>{desc}</p><span class="approach-end-arrow">↘</span></div>''' for i,(ic,title,desc) in enumerate(approaches))
